impl<S: gx::Slots, T: gx::Coef> gx::Transform<Point<S, T>> for gx::Unit<Point<(), T>> {
    type Output = Point<S, T>;
    #[inline(always)]
    fn transform(self, x: Point<S, T>) -> Point<S, T> {
        let v = self.into_inner().c;
        #[cfg(feature = "check-units")]
        {
        let u1 = v[2].mul_add(v[2], -T::from_i64(1));
            T::check_unit(&[u1]);
        }
        if let Some(xv) = gx::slots::values::<S, T, 3>(&x.c) {
        let t0 = v[2] * v[2];
        let t1 = v[2] * xv[2];
        let t2 = v[0] * t1;
        let t4 = v[1] * t1;
        let t6 = xv[2] * t0;
        let t7 = t2 * T::from_i64(2);
        let t8 = (-xv[0]).mul_add(t0, t7);
        let t9 = t4 * T::from_i64(2);
        let t10 = (-xv[1]).mul_add(t0, t9);
            return Point { c: gx::slots::from_values::<S, T, 3>([t8, t10, t6]) };
        }
        let m0 = v[2] * v[2];
        let m1 = v[0] * v[2];
        let m2 = v[1] * v[2];
        let m3 = -m0;
        let m4 = m1 * T::from_i64(2);
        let m5 = m2 * T::from_i64(2);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Point { c: [(x[0].scale(m3) + x[2].scale(m4)).0, (x[1].scale(m3) + x[2].scale(m5)).0, (x[2].scale(m0)).0] }
    }
}

