impl<S: gx::Slots, T: gx::Coef> gx::Transform<Translator<S, T>> for Point<(), T> {
    type Output = Translator<S, T>;
    #[inline(always)]
    fn transform(self, x: Translator<S, T>) -> Translator<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 3>(&x.c) {
        let t0 = v[2] * v[2];
        let t1 = xv[0] * t0;
        let t2 = xv[1] * t0;
        let t3 = xv[2] * t0;
        let t4 = -t2;
        let t5 = -t3;
            return Translator { c: gx::slots::from_values::<S, T, 3>([t1, t4, t5]) };
        }
        let m0 = v[2] * v[2];
        let m1 = -m0;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Translator { c: [(x[0].scale(m0)).0, (x[1].scale(m1)).0, (x[2].scale(m1)).0] }
    }
}

